import { definePlugin } from '#calm';
import { settings } from './storage.js';

// Local file storage. The 'file' resource (app/resources/file) holds the metadata;
// this plugin only reports its configuration to doctor and devtools.
export default definePlugin({
  name: 'storage-local',
  env: {
    UPLOAD_DIR: 'Folder for uploaded files (default ./uploads)',
    UPLOAD_MAX_MB: 'Largest upload in MB (default 10)',
    UPLOAD_ALLOWED_TYPES: 'Comma separated MIME types (default: images and PDF)',
  },
  setup(calm) {
    calm.doctor(() => {
      const findings = [];
      if (calm.config.mode === 'production') {
        findings.push({
          level: 'info',
          id: 'storage-local-production',
          title: 'Uploads are stored on local disk',
          detail: `Files live in ${settings().dir}. With several instances or ephemeral disks use @calmapi/storage-s3.`,
        });
      }
      return findings;
    });
    calm.devtools.panel('storage', () => {
      const s = settings();
      return { driver: 'local disk', directory: s.dir, maxMb: s.maxBytes / 1048576, allowedTypes: s.allowed };
    });
  },
});

import { mkdirSync, openSync, readSync, closeSync, unlinkSync, existsSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { randomUUID } from 'node:crypto';
import multer from 'multer';
import { badRequest } from '#calm';

// Local disk storage. Files get random names (never the uploaded name), the declared
// type must be on the allowlist, and the first bytes must match that type.

export const settings = () => ({
  dir: resolve(process.env.UPLOAD_DIR || './uploads'),
  maxBytes: Number(process.env.UPLOAD_MAX_MB || 10) * 1024 * 1024,
  allowed: (process.env.UPLOAD_ALLOWED_TYPES || 'image/png,image/jpeg,image/gif,image/webp,application/pdf').split(',').map((s) => s.trim()),
});

const EXT = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp', 'application/pdf': 'pdf', 'text/plain': 'txt', 'text/csv': 'csv' };

// Magic numbers for types we can verify. Others are accepted on the declared type alone.
const SIGNATURES = {
  'image/png': (b) => b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])),
  'image/jpeg': (b) => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff,
  'image/gif': (b) => b.subarray(0, 4).toString('latin1') === 'GIF8',
  'image/webp': (b) => b.subarray(0, 4).toString('latin1') === 'RIFF' && b.subarray(8, 12).toString('latin1') === 'WEBP',
  'application/pdf': (b) => b.subarray(0, 5).toString('latin1') === '%PDF-',
};

/** Types safe to display inline in a browser. Everything else downloads as an attachment. */
export const INLINE = new Set(['image/png', 'image/jpeg', 'image/gif', 'image/webp']);

export function uploadMiddleware(field = 'file') {
  const { dir, maxBytes, allowed } = settings();
  mkdirSync(dir, { recursive: true });
  const upload = multer({
    storage: multer.diskStorage({
      destination: dir,
      filename: (_req, file, cb) => cb(null, `${randomUUID()}.${EXT[file.mimetype] ?? 'bin'}`),
    }),
    limits: { fileSize: maxBytes, files: 1, fields: 10 },
    fileFilter: (_req, file, cb) => {
      if (!allowed.includes(file.mimetype)) return cb(badRequest(`File type ${file.mimetype} is not allowed. Allowed: ${allowed.join(', ')}`));
      cb(null, true);
    },
  }).single(field);

  return (req, res, next) =>
    upload(req, res, (err) => {
      if (!err) return next();
      if (err.code === 'LIMIT_FILE_SIZE') return next(badRequest(`File is larger than ${Math.round(maxBytes / 1048576)} MB`));
      if (err.name === 'MulterError') return next(badRequest(err.message));
      next(err);
    });
}

/** Verify the stored bytes match the declared type; deletes the file when they do not. */
export function verifySignature(file) {
  const check = SIGNATURES[file.mimetype];
  if (!check) return;
  const fd = openSync(file.path, 'r');
  const head = Buffer.alloc(16);
  readSync(fd, head, 0, 16, 0);
  closeSync(fd);
  if (!check(head)) {
    remove(file.filename);
    throw badRequest(`File content does not match ${file.mimetype}`);
  }
}

export const pathOf = (key) => join(settings().dir, key.replace(/[^\w.-]/g, ''));

export function remove(key) {
  const path = pathOf(key);
  if (existsSync(path)) unlinkSync(path);
}

import { resource, f } from '#calm';

// Uploaded files (metadata). Upload with POST /api/files/upload (multipart, field "file").
export default resource('file', {
  crud: ['list', 'read', 'delete'], // created only through the upload route
  fields: {
    originalName: f.string().readOnly().searchable().sortable(),
    mimeType: f.string().readOnly().filterable(),
    size: f.integer().readOnly().sortable(),
    key: f.string().hidden(), // storage location, never exposed
    owner: f.ref('user').owner().filterable(),
  },
  policy: {
    list: 'owner | admin',
    read: 'owner | admin',
    create: 'authenticated',
    update: 'none',
    delete: 'owner | admin',
  },
});

import { badRequest } from '#calm';
import { uploadMiddleware, verifySignature, pathOf, INLINE } from '#app/blocks/storage-local/storage.js';

export default (r) => {
  r.post(
    '/upload',
    { policy: 'authenticated', status: 201, summary: 'Upload a file (multipart/form-data, field "file")', middleware: [uploadMiddleware('file')] },
    async (ctx) => {
      const file = ctx.req.file;
      if (!file) throw badRequest('Send the file as multipart/form-data in a field named "file"');
      verifySignature(file);
      return ctx.service.create(
        { originalName: file.originalname.slice(0, 255), mimeType: file.mimetype, size: file.size, key: file.filename },
        ctx,
      );
    },
  );

  r.get('/:id/download', { policy: 'owner | admin', summary: 'Download a file' }, async (ctx) => {
    const doc = await ctx.service.model.findById(ctx.doc._id).select('+key').lean();
    const inline = INLINE.has(doc.mimeType);
    const headers = {
      'Content-Type': inline ? doc.mimeType : 'application/octet-stream',
      'Content-Disposition': `${inline ? 'inline' : 'attachment'}; filename*=UTF-8''${encodeURIComponent(doc.originalName)}`,
      'X-Content-Type-Options': 'nosniff',
      'Content-Security-Policy': "default-src 'none'; sandbox",
      'Cache-Control': 'private, max-age=0',
    };
    await new Promise((resolve, reject) => ctx.res.sendFile(pathOf(doc.key), { headers }, (err) => (err ? reject(err) : resolve())));
  });
};

import { ResourceService } from '#calm';
import { remove } from '#app/blocks/storage-local/storage.js';

export default class FileService extends ResourceService {
  async afterDelete(doc) {
    remove(doc.key);
  }
}
